const exceptions = $input.all().map(item => item.json);

const today = new Date();
today.setHours(0, 0, 0, 0);

const overdueItems = exceptions.filter(item => {
  if (!item.remediation_due_date) return false;

  const dueDate = new Date(item.remediation_due_date);
  if (Number.isNaN(dueDate.getTime())) return false;

  dueDate.setHours(0, 0, 0, 0);

  return (
    dueDate < today &&
    item.remediation_status !== "Closed"
  );
});

return [{
  json: {
    total_exceptions: exceptions.length,
    overdue_remediations: overdueItems.length,
    overdue_high_risk: overdueItems.filter(
      item => item.risk_severity === "High"
    ).length,
    overdue_items: overdueItems.map(item => ({
      control_code: item.control_code,
      risk_severity: item.risk_severity,
      remediation_owner: item.remediation_owner,
      remediation_due_date: item.remediation_due_date,
      remediation_status: item.remediation_status
    }))
  }
}];

const items = $input.all().map(item => item.json);

const controls = items.filter(item =>
  item.control_code && item.control_description
);

const evidence = items.filter(item =>
  item.evidence_name !== undefined
);

const exceptions = items.filter(item =>
  item.risk_severity !== undefined
);

const summary = items.find(item =>
  item.total_controls !== undefined
);

const evidenceCodes = new Set(
  evidence.map(item => item.control_code)
);

const results = controls.map(control => {
  const matchingEvidence = evidence.filter(
    item => item.control_code === control.control_code
  );

  let status = "Missing Evidence";

  if (matchingEvidence.length > 0) {
    const validEvidence = matchingEvidence.some(
      item =>
        item.evidence_status === "Submitted" &&
        item.evidence_quality === "Valid"
    );

    status = validEvidence ? "PASS" : "FAIL";
  }

  return {
    json: {
      control_code: control.control_code,
      control_description: control.control_description,
      compliance_status: status,
      evidence_count: matchingEvidence.length
    }
  };
});

return results;

const rows = $input.all().map(item => item.json);

const totalControls = rows.length;

const passed = rows.filter(
  item => item.compliance_status === "PASS"
).length;

const failed = rows.filter(
  item => item.compliance_status === "FAIL"
).length;

const missingEvidence = rows.filter(
  item => item.compliance_status === "Missing Evidence"
).length;

const compliancePercentage = totalControls > 0
  ? Number(((passed / totalControls) * 100).toFixed(2))
  : 0;

return [{
  json: {
    total_controls: totalControls,
    passed_controls: passed,
    failed_controls: failed,
    missing_evidence: missingEvidence,
    compliance_percentage: compliancePercentage
  }
}];

const exceptions = $input.all().map(item => item.json);

const openItems = exceptions.filter(
  item => item.remediation_status === "Open"
);

const severityCounts = {
  High: openItems.filter(item => item.risk_severity === "High").length,
  Medium: openItems.filter(item => item.risk_severity === "Medium").length,
  Low: openItems.filter(item => item.risk_severity === "Low").length
};

return [{
  json: {
    total_exceptions: exceptions.length,
    open_remediations: openItems.length,
    high_risk_open: severityCounts.High,
    medium_risk_open: severityCounts.Medium,
    low_risk_open: severityCounts.Low,
    remediation_owners: [...new Set(
      openItems.map(item => item.remediation_owner).filter(Boolean)
    )]
  }
}];
